package career.assistant.document.entity;
import jakarta.persistence.*; import java.time.OffsetDateTime; import java.util.UUID;
@Entity @Table(name="cover_letters", uniqueConstraints=@UniqueConstraint(name="uq_cover_letters_job",columnNames="job_id")) public class CoverLetter {
 @Id @GeneratedValue private UUID id; @Column(name="job_id",nullable=false) private UUID jobId; @Column(nullable=false) private String title; @Column(nullable=false,columnDefinition="TEXT") private String content; @Column(name="file_name") private String fileName; @Column(name="storage_path") private String storagePath; @Column(name="content_type") private String contentType; private boolean customized; @Column(name="customization_summary",columnDefinition="TEXT") private String customizationSummary; @Column(name="created_at",nullable=false) private OffsetDateTime createdAt;
 @PrePersist void create(){if(createdAt==null)createdAt=OffsetDateTime.now();} public UUID getId(){return id;} public UUID getJobId(){return jobId;} public void setJobId(UUID v){jobId=v;} public String getTitle(){return title;} public void setTitle(String v){title=v;} public String getContent(){return content;} public void setContent(String v){content=v;} public String getFileName(){return fileName;} public void setFileName(String v){fileName=v;} public String getStoragePath(){return storagePath;} public void setStoragePath(String v){storagePath=v;} public String getContentType(){return contentType;} public void setContentType(String v){contentType=v;} public boolean isCustomized(){return customized;} public void setCustomized(boolean v){customized=v;} public String getCustomizationSummary(){return customizationSummary;} public void setCustomizationSummary(String v){customizationSummary=v;} public OffsetDateTime getCreatedAt(){return createdAt;}
}
